<?php
declare(strict_types=1);
namespace Tests\Feature;
use App\Communications\CampaignUnsubscribeService; use App\Core\{Request,Response,Router,Session,View}; use App\Security\SecretCipher; use DateTimeImmutable; use PDO; use PHPUnit\Framework\TestCase;
final class CampaignRoutesTest extends TestCase {
 public function testAdminCampaignRoutesRequireAdminAndPublicUnsubscribeRequiresCsrfOnPost():void {$pdo=new PDO('sqlite::memory:');$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec('CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT,email TEXT,role TEXT,status TEXT)');$pdo->exec('CREATE TABLE communication_preferences(user_id INTEGER,category TEXT,email_enabled INTEGER,marketing_opted_in_at TEXT,PRIMARY KEY(user_id,category))');$pdo->exec('CREATE TABLE communication_campaigns(id INTEGER PRIMARY KEY)');$pdo->exec('CREATE TABLE communication_email_outbox(id INTEGER PRIMARY KEY,user_id INTEGER,event TEXT,status TEXT,payload_ciphertext TEXT)');$cipher=new SecretCipher(base64_encode(str_repeat('r',32)));$clock=static fn():DateTimeImmutable=>new DateTimeImmutable('2026-09-07 12:00:00');$unsub=new CampaignUnsubscribeService($pdo,$cipher,'https://cliplab.example',$clock);$token=$unsub->tokenFor(7);$router=new Router();$register=require dirname(__DIR__,2).'/routes/campaigns.php';$register($router,['pdo'=>$pdo,'view'=>new View(),'cipher'=>$cipher,'base_url'=>'https://cliplab.example','clock'=>$clock,'authenticated'=>static fn(Request $r,callable $n):Response=>Response::redirect('/login'),'admin_only'=>static fn(Request $r,callable $n):Response=>Response::redirect('/login')]);$_SESSION=[];self::assertSame('/login',$router->dispatch(Request::fake('GET','/admin/campanhas'))->header('Location'));$form=$router->dispatch(Request::fake('GET','/cancelar-inscricao?token='.rawurlencode($token)));self::assertSame(200,$form->status());self::assertStringContainsString('Cancelar inscrição',$form->body());self::assertSame(419,$router->dispatch(Request::fake('POST','/cancelar-inscricao',['token'=>$token]))->status());}
}
